package com.creatorhub.model; public class Collaboration {private int collabId,creatorId,voteCount,applicationCount; private String creatorName,title,category,description,requiredRole,status; private boolean voted; public int getCollabId(){return collabId;} public void setCollabId(int v){collabId=v;} public int getCreatorId(){return creatorId;} public void setCreatorId(int v){creatorId=v;} public int getVoteCount(){return voteCount;} public void setVoteCount(int v){voteCount=v;} public int getApplicationCount(){return applicationCount;} public void setApplicationCount(int v){applicationCount=v;} public String getCreatorName(){return creatorName;} public void setCreatorName(String v){creatorName=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getRequiredRole(){return requiredRole;} public void setRequiredRole(String v){requiredRole=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public boolean isVoted(){return voted;} public void setVoted(boolean v){voted=v;}}
